// Fixtures are generated by actual C# visibility/projection checks, never a user's save.
import {createServer} from 'vite';
import {chromium} from '@playwright/test';
import {readFile,mkdir} from 'node:fs/promises';
import assert from 'node:assert/strict';
const fixtures=await readFile('../test-results/planet-fixtures.json','utf8');
const server=await createServer({configFile:false,root:process.cwd(),server:{host:'127.0.0.1',port:0},appType:'mpa'});
let browser,checks=0;const check=(ok,name)=>{assert.ok(ok,name);checks++;console.log('PASS '+name);};
try{
 await server.listen();browser=await chromium.launch({channel:'msedge',headless:true});
 const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.route('**/planet-fixtures.json',route=>route.fulfill({contentType:'application/json',body:fixtures}));
 await page.goto(`http://127.0.0.1:${server.httpServer.address().port}/tests/planet-fixture.html`);
 const dialog=page.getByRole('dialog');
 const open=async name=>{await page.getByRole('button',{name:`Open ${name}`,exact:true}).click();await dialog.waitFor();};
 const close=async()=>{await page.getByRole('button',{name:'Close planet statistics'}).click();await dialog.waitFor({state:'detached'});};
 const fact=async(label,within=dialog)=>within.locator('.planetFacts div').filter({has:page.locator('dt',{hasText:new RegExp('^'+label+'$')})}).locator('dd').allTextContents();
 await open('own');
 check((await dialog.innerText()).includes('Current observation at last refresh'),'Current observation is qualified as a snapshot');
 check(JSON.stringify(await fact('Total ships including scouts'))==='["18","0"]','Ship totals include scouts without duplicating combat hulls');
 check((await fact('Colony income'))[0]==='18 credits / turn','Own colony income comes from server');
 check((await fact('Material resources'))[0]==='Not measured'&&(await fact('Inhabitants / population'))[0]==='Not measured','Unimplemented resources and population are explicit');
 check(await page.getByRole('button',{name:'Close planet statistics'}).evaluate(e=>e===document.activeElement),'Initial focus goes to Close');
 await page.keyboard.press('Tab');check(await dialog.evaluate(e=>e.contains(document.activeElement)),'Tab remains inside modal');
 await dialog.getByRole('heading',{name:'Ship breakdown'}).click();check(await dialog.isVisible(),'Clicking content keeps modal open');
 await page.keyboard.press('Escape');await dialog.waitFor({state:'detached'});
 check(await page.getByRole('button',{name:'Open own',exact:true}).evaluate(e=>e===document.activeElement),'Escape closes and restores opener focus');
 await open('deep');let text=await dialog.innerText();
 check(text.includes('Last-known observation')&&text.includes('4 turn(s) ago')&&text.includes('May be stale')&&text.includes('arrival / before combat'),'Deep survey is dated with age and phase');
 check((await fact('Collectors'))[0]==='4'&&(await fact('Total ships including scouts'))[0]==='5','Historical measurements retain original counts after hidden mutations');
 check(text.includes('Torpedo boat: 2')&&!text.includes('99')&&!text.includes('77'),'Known hull breakdown excludes hidden later counts');
 await close();await open('close');text=await dialog.innerText();
 check(text.includes('Estimated enemy combat fleet: 1-4 ships.')&&(await fact('Combat ships'))[0]==='Unknown','Close survey shows range without exact count');
 await close();await open('distant');check((await fact('Ownership'))[0]==='Ember Empire'&&(await fact('Collectors'))[0]==='Unknown','Distant report preserves ownership only');
 await close();await open('lost');check((await fact('Ownership'))[0]==='Unknown'&&(await fact('Total ships including scouts'))[0]==='Unknown','Lost scout does not upgrade partial intel');
 await close();await open('battle');check((await fact('Combat ships'))[0]==='3'&&(await fact('Total ships including scouts'))[0]==='Unknown','Battle report does not invent unobserved scouts');
 await close();await open('charted');check((await dialog.innerText()).includes('Charted only')&&(await fact('Ownership'))[0]==='Unknown','Charted system is not labelled surveyed');
 await close();await open('unknown');check((await dialog.innerText()).includes('Uncharted')&&(await fact('Collectors'))[0]==='Unknown','Uncharted system remains unknown');
 await page.mouse.click(2,2);await dialog.waitFor({state:'detached'});check(await page.getByRole('button',{name:'Open unknown',exact:true}).evaluate(e=>e===document.activeElement),'Backdrop closes and restores focus');
 await open('classic');check((await dialog.innerText()).includes('one generic class')&&!(await dialog.innerText()).includes('Torpedo boat:'),'Classic ships do not fabricate typed hulls');await close();
 await page.setViewportSize({width:390,height:640});await open('own');
 check(await dialog.evaluate(e=>e.scrollWidth<=e.clientWidth&&e.getBoundingClientRect().height<=innerHeight),'Mobile modal fits viewport without horizontal overflow');
 check(await page.locator('.planetScroll').evaluate(e=>e.scrollHeight>e.clientHeight),'Long mobile dossier scrolls internally');
 await page.locator('.planetScroll').evaluate(e=>e.scrollTop=e.scrollHeight);
 check(await page.getByRole('button',{name:'Close planet statistics'}).isVisible(),'Close remains accessible while scrolling');
 await mkdir('../test-results',{recursive:true});await page.screenshot({path:'../test-results/planet-mobile.png'});
 await close();await page.setViewportSize({width:1280,height:900});await open('deep');await page.screenshot({path:'../test-results/planet-desktop.png'});await close();
 for(let i=0;i<3;i++){await open('own');await close();}
 check(await page.evaluate(()=>document.body.style.overflow===''),'Repeated open/close restores page scrolling');
 check(errors.length===0,'No browser errors');
 console.log(`${checks} planet component checks passed using server-projected fixtures.`);
}finally{if(browser)await browser.close();await server.close();}
